 "content": "def transform(grid):
    """Color 5 connects the two markers along each row/column axis."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    points = {}
    for r in range(h):
        for c in range(w):
            if out[r][c]:
                points.setdefault(out[r][c], []).append((r, c))
    # In the demonstration, a 1 and 2 are joined by a 5-colored L-like
    # connector: the 1's row reaches the 2's column; the 2's row reaches
    # the 1's column. Preserve both endpoints.
    if 1 in points and 2 in points:
        r1,c1=points[1][0]; r2,c2=points[2][0]
        # Join via the two orthogonal arms as shown by the sample.
        for c in range(min(c1,c2)+1, max(c1,c2)):
            out[r2][c]=5
        for r in range(min(r1,r2)+1, max(r1,r2)):
            out[r][c2]=5
        # Connection to corner at (r1,c2), shown as an additional 5 cell
        # on the 1 row immediately before the corner in the sample geometry.
        if c1 != c2 and c1+1 < w:
            out[r1][c1+1]=5
        if r1>0 and c2<w:
            out[r1-1][c2]=1
    return out
