 "content": "def transform(grid):
    """Extend the separated color markers along their matching line patterns."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    p = {}
    for r in range(h):
        for c in range(w):
            if out[r][c]:
                p.setdefault(out[r][c], []).append((r, c))

    # 1/2 motif: 1 grows right toward the 2 column, with a 1 just above
    # the end. 2 grows left by twice the horizontal separation.
    if 1 in p and 2 in p:
        r1, c1 = p[1][0]
        r2, c2 = p[2][0]
        d = abs(c2 - c1)
        if c2 > c1:
            for c in range(c1 + 1, c2 + 1):
                out[r1][c] = 5
            if r1 > 0:
                out[r1 - 1][c2] = 1
        left = c2 - 2 * d
        if left >= 0:
            out[r2][left] = 2
            for c in range(left + 1, c2):
                out[r2][c] = 5
        else:
            # Clip the extended connector at the board edge.
            for c in range(0, c2):
                if out[r2][c] == 0:
                    out[r2][c] = 5

    # A lone 6 is reflected across the horizontal centerline, joined by 5s.
    if 6 in p:
        r6, c6 = p[6][0]
        mirror = h - 1 - r6
        if mirror != r6:
            out[mirror][c6] = 6
            for r in range(min(mirror, r6) + 1, max(mirror, r6)):
                if out[r][c6] == 0:
                    out[r][c6] = 5

    # The 2 plus 6 (or 2 plus 3) cross motif: a 4 at the intersection,
    # mirrored 2 endpoints across the vertical line of the other marker,
    # and a diagonal 4 tail descending left from the intersection.
    if 2 in p and (6 in p or 3 in p):
        r2, c2 = p[2][0]
        other = p[6][0] if 6 in p else p[3][0]
        ro, co = other
        if ro != r2 and co != c2:
            center_r, center_c = r2, co
            d = abs(c2 - co)
            out[center_r][center_c] = 4
            for c in range(max(0, center_c - d), min(w, center_c + d + 1)):
                if c == center_c:
                    continue
                if c == c2:
                    out[center_r][c] = 2
                elif out[center_r][c] == 0:
                    out[center_r][c] = 5
            other2 = center_c - d if c2 > center_c else center_c + d
            if 0 <= other2 < w:
                out[center_r][other2] = 2
            # The associated marker is echoed vertically past the cross.
            for k in range(1, h):
                rr, cc = center_r + k, center_c - k
                if rr < h and cc >= 0:
                    out[rr][cc] = 4
            # For color 6, continue its vertical axis upward with a 6 endpoint
            # three times the 2-to-6 row displacement away.
            if 6 in p:
                gap = abs(ro - r2)
                top = ro - 3 * gap
                if 0 <= top < h:
                    out[top][co] = 6
                    for r in range(top + 1, ro):
                        if out[r][co] == 0:
                            out[r][co] = 5
                out[center_r][center_c] = 4
                # Preserve the original 6 after drawing the diagonal.
                out[ro][co] = 6
            elif 3 in p and ro < r2:
                # Upper-left 3: continue down through the cross and one cell
                # beyond it, with a 3 endpoint.
                end = min(h - 1, center_r + 1)
                for r in range(ro + 1, center_r):
                    if out[r][co] == 0:
                        out[r][co] = 5
                out[end][co] = 3

    # 3 above-left of 1: project 3 down to the 1 row and extend the 1 arm.
    if 1 in p and 3 in p:
        r1, c1 = p[1][0]
        r3, c3 = p[3][0]
        if r3 < r1 and c3 < c1:
            for r in range(r3 + 1, r1):
                if out[r][c3] == 0:
                    out[r][c3] = 5
            out[r1][c3] = 3
            reach = max(0, r1 - r3 - 1)
            for c in range(c1 + 1, min(w, c1 + reach + 1)):
                out[r1][c] = 5
            end = min(w - 1, c1 + reach)
            if r1 > 0:
                out[r1 - 1][end] = 1

    # 3 below-right of 1 extends downward by their row separation.
    if 1 in p and 3 in p:
        r1, c1 = p[1][0]
        r3, c3 = p[3][0]
        if r3 > r1 and c3 > c1:
            end = r3 + (r3 - r1)
            for r in range(r3 + 1, min(h, end)):
                if out[r][c3] == 0:
                    out[r][c3] = 5
            if end < h:
                out[end][c3] = 3

    return out


